/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base forward-substitution kernel:
#   L is a lower-triangular matrix.
#   We solve L x = b in-place in x.
#
# We write the computation using a scalar accumulator `s` to keep the
# running dot-product in a register, avoiding repeated stores to x[i].
@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        s: DATA_TYPE
        s = 0.0
        for j in seq(0, i):
            s += L[i, j] * x[j]
        x[i] = (b[i] - s) / L[i, i]


# ---------------------------------------------------------------------
# Scheduling: improve inner-loop efficiency
#
#  - The outer loop over i carries true dependencies (forward solve),
#    so we keep it strictly sequential.
#  - The inner loop over j has only a reduction dependence on `s`,
#    so we can safely transform it.
#  - We tile j by a factor of 4 and fully unroll the inner tile loop.
#    This exposes more instruction-level parallelism and gives the C
#    compiler a simple, straight-line body to auto-vectorize.
# ---------------------------------------------------------------------

kernel_trisolv = kernel_trisolv_base

# Tile and partially unroll the inner loop over j.
# Use a guarded tail so we handle arbitrary n (and hence arbitrary i).
j_loop = kernel_trisolv.find_loop("j")
kernel_trisolv = divide_loop(kernel_trisolv, j_loop, 4, ("jo", "ji"), tail="guard")

# The ji-loop now has a constant trip count of 4; unroll it completely.
ji_loop = kernel_trisolv.find_loop("ji")
kernel_trisolv = unroll_loop(kernel_trisolv, ji_loop)

# Clean up algebra and remove any trivial loops/branches introduced
# by the transformations above.
kernel_trisolv = simplify(kernel_trisolv)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_trisolv (/*ctxt=*/NULL,
                  n,
                  (DATA_TYPE*)POLYBENCH_ARRAY(L),
                  (DATA_TYPE*)POLYBENCH_ARRAY(x),
                  (DATA_TYPE*)POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}

