/*
 * Kernel implementation in Exo.
 *
 * The base kernel directly mirrors the original PolyBench trisolv
 * forward-substitution:
 *
 *   for i = 0..n-1:
 *     x[i] = b[i]
 *     for j = 0..i-1:
 *       x[i] -= L[i,j] * x[j]
 *     x[i] /= L[i,i]
 *
 * We then apply a schedule that:
 *   - Splits the inner j-loop into blocks of size 4 (divide_loop),
 *   - Fully unrolls the 4-iteration inner loop (unroll_loop),
 *   - Simplifies the resulting code (simplify),
 *   - Renames the optimized procedure back to `kernel_trisolv`.
 *
 * This keeps the i-loop order (and thus the triangular dependency on x)
 * unchanged, while improving ILP and making the inner loop friendlier
 * to SIMD and instruction scheduling. The order of j-iterations for
 * each i is preserved exactly, so the floating-point computation is
 * mathematically equivalent to the original.
 */

/* Exo kernel:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *          # scheduling primitives
from exo.libs.memories import DRAM        # standard DRAM memory


# Base kernel: straightforward forward substitution on a lower-triangular matrix.
@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Initialize x[i] from the right-hand side.
        x[i] = b[i]

        # Apply the forward-substitution update using already computed x[0..i-1].
        for j in seq(0, i):
            x[i] = x[i] - L[i, j] * x[j]

        # Divide by the diagonal element to finish computing x[i].
        x[i] = x[i] / L[i, i]


# === Scheduling ===
# We only transform the inner j-loop; the outer i-loop order (and its
# loop-carried dependence on x) is preserved exactly.

# 1. Tile the j-loop into an outer loop `jo` and an inner loop `ji`
#    with a constant factor of 4. The 'cut' tail strategy emits a
#    separate cleanup loop for any leftover iterations.
kernel_trisolv_tiled = divide_loop(
    kernel_trisolv_base,
    "j",                 # loop to split
    4,                   # tile factor
    ["jo", "ji"],        # new loop indices: outer, inner
    tail="cut",
)

# 2. Fully unroll the small inner loop over `ji` (which has constant
#    trip-count 4 after the split). This exposes four independent
#    multiply-subtracts per iteration of `jo`, improving ILP and
#    making the code easier for the C compiler to vectorize.
kernel_trisolv_unrolled = unroll_loop(kernel_trisolv_tiled, "ji")

# 3. Run the simplifier to clean up any algebraic and control-flow
#    redundancies introduced by the transformations.
kernel_trisolv_opt = simplify(kernel_trisolv_unrolled)

# 4. Export the scheduled kernel under the original expected name.
kernel_trisolv = rename(kernel_trisolv_opt, "kernel_trisolv")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

